import sys
from functools import lru_cache

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    strengths = sorted([int(x) for x in lines[1].split()], reverse=True)

    m = int(lines[2])
    actions = []
    for i in range(m):
        parts = lines[3 + i].split()
        actions.append((parts[0], int(parts[1])))

    team_state = [0, 0]

    @lru_cache(maxsize=None)
    def minimax(action_idx, available):
        if action_idx == m:
            return team_state[0] - team_state[1]

        action_type, team = actions[action_idx]

        if action_type == 'b':
            # Ban: choose to ban a hero to minimize opponent's advantage
            banned = -1
            if team == 1:
                # Team 1 wants to minimize (team1 - team2), so maximizes (team2 - team1)
                best_val = float('inf')
                for i in available:
                    if i >= len(strengths):
                        continue
                    new_available = available & ((1 << len(strengths)) - (1 << i))
                    if new_available != available:
                        val = -minimax(action_idx + 1, new_available)
                        best_val = min(best_val, val)
                return team_state[0] - team_state[1] + best_val
            else:
                # Team 2 wants to minimize (team1 - team2), so wants to maximize (team2 - team1)
                best_val = float('-inf')
                for i in available:
                    if i >= len(strengths):
                        continue
                    new_available = available & ((1 << len(strengths)) - (1 << i))
                    if new_available != available:
                        val = -minimax(action_idx + 1, new_available)
                        best_val = max(best_val, val)
                return team_state[0] - team_state[1] + best_val

        elif action_type == 'p':
            # Pick: choose to pick a hero
            if team == 1:
                # Team 1 wants to maximize (team1 - team2)
                best_val = float('-inf')
                for i in available:
                    if i >= len(strengths):
                        continue
                    team_state[0] += strengths[i]
                    new_available = available & ((1 << len(strengths)) - (1 << i))
                    if i == available.bit_count() - 1 or i < available.bit_count() - 1:
                        new_available = available & ~((1 << (i + 1)) - 1)
                        best_val = min(best_val, minimax(action_idx + 1, new_available))
                    else:
                        val = minimax(action_idx + 1, new_available)
                        best_val = max(best_val, val)
                    team_state[0] -= strengths[i]
                return best_val
            else:
                # Team 2 wants to maximize (team2 - team1) = minimize (team1 - team2)
                best_val = float('inf')
                for i in available:
                    if i >= len(strengths):
                        continue
                    team_state[1] += strengths[i]
                    new_available = available & ((1 << len(strengths)) - (1 << i))
                    val = minimax(action_idx + 1, new_available)
                    best_val = min(best_val, val)
                    team_state[1] -= strengths[i]
                return best_val

    result = minimax(0, (1 << len(strengths)) - 1)
    return str(result)

import sys

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, len(lines)):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * (n + 1)
    component_sizes = []

    for start in range(1, n + 1):
        if visited[start]:
            continue

        queue = [start]
        visited[start] = True
        size = 0

        idx = 0
        while idx < len(queue):
            u = queue[idx]
            idx += 1
            size += 1
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    queue.append(v)

        component_sizes.append(size)

    min_roads = float('inf')
    lucky_numbers = []

    def generate_lucky(current, length):
        if length == 0:
            lucky_numbers.append(current)
            return
        generate_lucky(current * 10 + 4, length - 1)
        generate_lucky(current * 10 + 7, length - 1)

    generate_lucky(0, 5)
    lucky_numbers = [l for l in lucky_numbers if 1 <= l <= n]

    if not component_sizes:
        return "-1\n"

    min_components_needed = {0: 0}

    for size in component_sizes:
        new_entries = {}
        for s, cnt in min_components_needed.items():
            new_size = s + size
            if new_size <= n:
                new_cnt = cnt + 1
                if new_size not in min_components_needed or new_cnt < min_components_needed[new_size]:
                    min_components_needed[new_size] = new_cnt
                    new_entries[new_size] = new_cnt

        min_components_needed.update(new_entries)

    for lucky in lucky_numbers:
        if lucky in min_components_needed:
            roads_needed = min_components_needed[lucky] - 1
            min_roads = min(min_roads, roads_needed)

    if min_roads == float('inf'):
        return "-1\n"
    else:
        return f"{min_roads}\n"

