        # Check diagonal squares
        # A diagonal square has corners at (r, c), (r, c+k), (r+sign*(k), c+sign*(k)), etc.
        # Actually, it's a diamond shape rotated 45 degrees

        # For a diagonal square with radius k (half-diagonal length):
        # The coordinates form a diamond: |(r - center_r)| + |(c - center_c)| = k
        # It must be at least 2x2, which means radius at least 1
        # Center must be at least 1 from each boundary

        for center_r in range(1, n - 1):
            for center_c in range(1, m - 1):
                for radius in range(1, min(center_r, center_c, n - 1 - center_r, m - 1 - center_c)):
                    # build the square (diamond shape)
