def solution(input_string):
    lines = input_string.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Parse clauses
    clauses = []
    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        k = parts[0]
        clause_literals = parts[1:]
        clauses.append(clause_literals)

    # Track variable assignments (None = unassigned, 0 = false, 1 = true)
    assignment = [None] * (m + 1)
    result_vars = [0] * (m + 1)

    def is_literal_satisfied(literal, var_idx):
        """Check if a literal is satisfied given current assignments"""
        abs_val = abs(literal)
        sign = 1 if literal > 0 else -1

        if assignment[var_idx] is None:
            return sign == 1  # If not assigned, assume true for this check
        elif assignment[var_idx] == 1:
            return sign == 1
        else:  # assignment is 0
            return sign == -1
        return False

    def check_clause_satisfied(clause):
        """Check if a clause is satisfied by any literal"""
        for lit in clause:
            if is_literal_satisfied(lit, abs(lit)):
                return True
        return False

    def find_unsatisfied_clause():
        """Find a clause that is NOT satisfied"""
        for clause in clauses:
            if not check_clause_satisfied(clause):
                return clause
        return None

    def solve():
        """Backtracking search for satisfiable assignment"""
        # If all variables assigned and all clauses satisfied, we're done
        if all(a is not None for a in assignment[1:]):
            # Verify all clauses are satisfied
            for clause in clauses:
                if not check_clause_satisfied(clause):
                    return None
            # Extract result
            result = [str(result_vars[i]) for i in range(m + 1)]
            return ''.join(result[1:])

        # Find the first unassigned variable
        var_idx = assignment.index(None)

        # Try setting assignment[var_idx] = 1 (true)
        assignment[var_idx] = 1
        result_vars[var_idx] = 1

        # Check if this creates any unsatisfied clause that we can't fix
        if solve():
            return ''.join(result_vars[1:])

        # Backtrack: try setting assignment[var_idx] = 0 (false)
        assignment[var_idx] = 0
        result_vars[var_idx] = 0

        # Check if this creates any unsatisfied clause
        unsat = find_unsatisfied_clause()
        if unsat is None:
            # All clauses satisfied with this assignment
            if all(a is not None for a in assignment[1:]):
                result = [str(result_vars[i]) for i in range(m + 1)]
                return ''.join(result[1:])

        # Continue backtracking
        return solve()

    result = solve()
    if result:
        return f"YES\n{result}"
    else:
        return "NO"

