def is_beautiful(mat, n, m, r1, r2, c1, c2):
    # Check row conditions: each row must have at most 1 odd-count char
    for r in range(r1, r2 + 1):
        row_chars = [ord(mat[r][c]) - ord('a') for c in range(c1, c2 + 1)]
        if not can_form_palindrome(row_chars):
            return False

    # After rows are palindromic, check if columns can also form palindromes
    # For each column, collect characters from rows
    for c in range(c1, c2 + 1):
        col_chars = [ord(mat[r][c]) - ord('a') for r in range(r1, r2 + 1)]
        if not can_form_palindrome(col_chars):
            return False

    return True

def can_form_palindrome(char_list):
    # Can these characters form a palindrome?
    # Yes if at most 1 character has odd count
    freq = [0] * 26
    for c in char_list:
        freq[c] += 1
    odd_count = sum(1 for x in freq if x % 2 == 1)
    return odd_count <= 1

