def solution(data):
    n_str = data.split('\n')[0].strip()
    if not n_str:
        return '1'
    n = int(n_str)

    if n == 1:
        return '1'

    adj = [[] for _ in range(n + 1)]
    for i in range(1, n):
        line = data.split('\n')[i].strip()
        if line:
            u, v = map(int, line.split())
            adj[u].append(v)
            adj[v].append(u)

    # dp[u] = dictionary {size -> max_completed_product}
    # size: size of component containing u
    # max_completed_product: max product of completed components in subtree

    # Use iterative tree DP with BFS order (bottom-up)
    parent = [0] * (n + 1)
    order = []
    stack = [1]
    parent[1] = 0

    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            if v != parent[u]:
                parent[v] = u
                stack.append(v)

    # Process in reverse order (bottom-up)
    dp = [{} for _ in range(n + 1)]

    for u in reversed(order):
        # Start with u forming a component of size 1 with no completed components
        dp[u][1] = 1

        for v in adj[u]:
            if v == parent[u]:
                continue

            v_dp = dp[v]
            u_dp = dp[u]
            new_dp = {}
            u_sizes = list(u_dp.keys())

            # Initialize with existing states from u (cut v's edge)
            for sz, prod in u_dp.items():
                # Option 1: Cut edge to v
                max_v_prod = max(v_dp.values())
                for v_sz, v_prod in v_dp.items():
                    new_prod = prod * v_prod
                    new_dp[sz] = max(new_dp.get(sz, 0), new_prod)
                break  # Don't add multiple times
            else:
                # If u_dp has only one element, init with all cut options
                max_v_prod = max(v_dp.values())
                for v_sz, v_prod in v_dp.items():
                    new_prod = u_dp[1] * v_prod
                    new_dp[1] = max(new_dp.get(1, 0), new_prod)

            # Merge u and v components
            for sz_u in u_sizes:
                for sz_v, prod_v in v_dp.items():
                    new_sz = sz_u + sz_v
                    new_prod = u_dp[sz_u] * prod_v
                    new_dp[new_sz] = max(new_dp.get(new_sz, 0), new_prod)
                break  # Avoid duplicate processing

            dp[u] = new_dp

    # Answer is max value across all sizes for root
    if dp[1]:
        return str(max(dp[1].values()))
    return '1'

