        # Count primes directly with simple trial division
        def is_prime(n):
            if n < 2:
                return False
            if n == 2:
                return True
            if n % 2 == 0:
                return False
            if n % 3 == 0:
                return False
            i = 5
            while i * i <= n:
                if n % i == 0 or n % (i + 2) == 0:
                    return False
                i += 6
            return True

        for num in range(start, end + 1):
            if is_prime(num):
                if num == 2 or num % 4 == 1:
                    result += 1
    else:
        # Use segmented sieve for larger ranges
        limit = int(r**0.5) + 1
        is_prime_small = [True] * limit
        is_prime_small[0] = is_prime_small[1] = False

        for i in range(2, limit):
            if is_prime_small[i]:
                for j in range(i * i, limit, i):
                    is_prime_small[j] = False

        precomputed_primes = [i for i, p in enumerate(is_prime_small) if p]

        block_size = 500000
        num = 0
        s = start
        while s <= end:
            e = min(s + block_size - 1, end)
            size = e - s + 1
            is_prime_range = [True] * size

            for p in precomputed_primes:
                if p * p > e:
                    break

                first = max(p * p, ((s + p - 1) // p) * p)
                idx = first - s
                for j in range(idx, size, p):
                    is_prime_range[j] = False

            for i in range(size):
                num = s + i
                if is_prime_range[i]:
                    if num == 2 or num % 4 == 1:
                        result += 1
            s = e + 1

    return str(result) + '\n'

