        r.append(ri_val)

    # Build adjacency list: sheep i and j are connected if their intervals overlap
    # Two intervals [l[i], r[i]] and [l[j], r[j]] overlap iff max(l[i], l[j]) <= min(r[i], r[j])
    adj = [[] for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            if max(l[i], l[j]) <= min(r[i], r[j]):
                adj[i].append(j)

    # Find connected components using BFS and sort components by l value
    result = []
    used = [False] * n

    for i in range(n):
        if not used[i]:
            # BFS to find all sheep in this component
            component = []
            queue = [i]
            used[i] = True
            visited = {i}

            while queue:
                curr = queue.pop(0)
                component.append(curr)

                for neighbor in adj[curr]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        used[neighbor] = True
                        queue.append(neighbor)

            # Sort component by starting position l (primary)
            component.sort(key=lambda x: l[x])
            result.extend(component)

    # Output sheep indices (1-indexed)
    return " ".join(str(x + 1) for x in result)

