def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    # Parse spaceships
    spaceships = []
    for i in range(n):
        x, y = map(int, lines[i+1].split())
        spaceships.append(((x, y), i + 1))  # (coordinate, index)

    # Parse bases
    bases = []
    for i in range(n):
        x, y = map(int, lines[i + n + 1].split())
        bases.append(((x, y), i + 1))  # (coordinate, index)

    def orientation(p, q, r):
        """Returns orientation of ordered triplet (p, q, r)"""
        val = (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1])
        if abs(val) < 1e-9:
            return 0  # Collinear
        return 1 if val > 0 else 2  # Clockwise or Counterclockwise

    def on_segment(p, q, r):
        """Check if point q lies on segment pr"""
        return (min(p[0], r[0]) <= q[0] <= max(p[0], r[0]) and
                min(p[1], r[1]) <= q[1] <= max(p[1], r[1]))

    def segments_intersect(p1, p2, p3, p4):
        """Check if segment p1-p2 intersects segment p3-p4"""
        o1 = orientation(p1, p2, p3)
        o2 = orientation(p1, p2, p4)
        o3 = orientation(p3, p4, p1)
        o4 = orientation(p3, p4, p2)

        # General case: proper intersection
        if o1 != o2 and o3 != o4:
            return True

        # Special cases: collinear points
        if o1 == 0 and on_segment(p1, p3, p2):
            return True
        if o2 == 0 and on_segment(p1, p4, p2):
            return True
        if o3 == 0 and on_segment(p3, p1, p4):
            return True
        if o4 == 0 and on_segment(p3, p2, p4):
            return True

        return False

    def check_matching(matching):
        """Check if all segments in matching are non-intersecting"""
        for (s_idx, b_idx1) in matching.items():
            for (s_idx2, b_idx2) in matching.items():
                if s_idx1 > s_idx or s_idx2 > s_idx2:
                    continue
                p1 = spaceships[s_idx1 - 1][0]
                p2 = spaceships[s_idx2 - 1][0]
                p3 = bases[b_idx1 - 1][0]
                p4 = bases[b_idx2 - 1][0]
                if s_idx1 == s_idx2 and b_idx1 == b_idx2:
                    continue
                if p1 != p2 and p3 != p4:
                    if segments_intersect(p1, p2, p3, p4):
                        return False
        return True

    # Try random matchings
    for attempt in range(min(5000, n * 5)):
        mapping = list(range(1, n + 1))
        random.shuffle(mapping)

        result = []
        valid = True

        for i in range(n):
            result.append(str(mapping[i]))

        # Verify this mapping works
        segs = []
        for s_idx in range(n):
            b_idx = int(result[s_idx])
            segs.append((spaceships[s_idx][0], bases[b_idx - 1][0]))

        valid = True
        for i in range(len(segs)):
            for j in range(i + 1, len(segs)):
                if segments_intersect(segs[i][0], segs[i][1], segs[j][0], segs[j][1]):
                    valid = False
                    break
            if not valid:
                break

        if valid:
