        return '0\n'

    n, m = map(int, lines[0].split())
    filters = []
    for i in range(1, m + 1):
        filters.append(lines[i])

    MOD = 1000000009

    # Filter lengths
    lens = [len(f) for f in filters]

    # State: tuple of (pos_in_filter_for_each_filter, completed_for_each_filter)
    # pos: current position in filter (0 to len(f)-1 means not completed, len(f) means completed)
    start_state = (0,) * m  # All filters at position 0
    dp = {start_state: 1}

    for _ in range(n):
        new_dp = {}
        for state, count in dp.items():
            # Try all characters
            for c in 'ACGT':
                for j in range(m):
                    f_len = lens[j]
                    pos = state[j]
                    # Filter completed or we try to match
                    next_pos = pos + 1 if pos < f_len else pos

                    # Check if this transition works (character matches if not completed)
                    if pos < f_len:
                        if filters[j][pos] != c:
                            next_pos = pos  # stay at same position if mismatch
                        else:
                            next_pos += 1

                    # Actually, let me reconsider: if we advance past end, we complete
                    if pos < f_len and filters[j][pos] == c:
                        next_pos += 1

                    # Build new state
                    new_state = list(state)
                    new_state[j] = next_pos

                    ns = tuple(new_state)
                    if ns not in new_dp or new_dp[ns] == 0:
                        new_dp[ns] = 0
                    new_dp[ns] = (new_dp[ns] + count) % MOD

        dp = new_dp

    # Count states where at least one filter has completed (pos == len(f))
    result = 0
    for state, count in dp.items():
        if any(state[j] == lens[j] for j in range(m)):
            result = (result + count) % MOD

    return str(result) + '\n'


