def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)

    def bfs(start):
        dist = [-1] * (n + 1)
        dist[start] = 0
        q = deque([start])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    q.append(v)
        return dist

    # Compute all-pairs shortest distances
    dist = [bfs(i) for i in range(1, n + 1)]

    max_total = -1
    best_path = None

    # Try all valid 4-city ordered paths
    # Fix cities B and C, find best A and D
    for i in range(1, n + 1):  # B
        for j in range(1, n + 1):  # C
            if i == j:
                continue

            if dist[i-1][j] == -1:
                continue

            best_a = -1
            best_d = -1
            best_total = -1

            # Find best A (maximizes d(A,B)) where all 4 cities are distinct
            for k in range(1, n + 1):
                if k != i and k != j:
                    if dist[k-1][i] != -1:
                        if dist[k-1][i] > best_total:
                            best_total = dist[k-1][i]
                            best_a = k

            if best_a == -1:
                continue

            # Find best D (maximizes d(C,D)) where all 4 cities are distinct
            for l in range(1, n + 1):
                if l != i and l != j and l != best_a:
                    if dist[j-1][l] != -1:
                        total = dist[best_a-1][i] + dist[i-1][j] + dist[j-1][l]
                        if total > best_total:
                            best_total = total
                            best_d = l

            if best_d == -1:
                continue

            best_total = dist[best_a-1][i] + dist[i-1][j] + dist[j-1][best_d]

            if best_total > max_total:
                max_total = best_total
                best_path = (best_a, i, j, best_d)

    if best_path:
        return f"{best_path[0]} {best_path[1]} {best_path[2]} {best_path[3]}"
    return ""

