    # DP
    for length in range(2, n):  # length = number of edges in subpolygon
        for i in range(n - length + 1):
            j = i + length

            # dp[i][j] is subpolygon on vertices i, i+1, ..., j
            # We can split at k where i < k < j
            # Triangle (i, k, j) must be valid if all vertices between i and j stay on the same side as polygon interior
            valid = False

            # Determine reference point for orientation
            if j == i + 1:
