    def mod_pow(base, exp):
        return pow(base, exp, MOD)

    def mod_inv(a):
        return pow(a, MOD - 2, MOD)

    result = 0

    # E[A_i] for single borders
    for i in range(1, n):
        term = mod_inv(mod_pow(k, n - i))
        result = (result + term) % MOD

