        # Kosaraju's algorithm
        stack = []
        for i in range(2 * n):
            if scc[i] == -1:
                dfs2(i, stack)

        comp = [-1] * (2 * n)
        for i in range(2 * n):
            if scc[i] == -1:
                dfs3(scc[i], comp)

        # Check for contradiction
        possible = True
        ans = [False] * n  # True = inside (variable 2*i assigned True)

