            d = len(str(i))
            val = (val * pow(10, d, MOD) + i) % MOD
        _, total_digits = 0, sum(len(str(x)) for x in range(a, b + 1))
        return val, total_digits

    def compute_repeat(n, inner):
        if not isinstance(inner, tuple):
            inner_val = inner % MOD
            inner_digits = len(str(inner))
        else:
            inner_val, inner_digits = inner
        shift = pow(10, inner_digits, MOD)
        result = 0
        for _ in range(n):
            result = (result * shift + inner_val) % MOD
        return result, inner_digits * n

    pos = 0
    final_val, final_digits = parse_expr()
    return final_val

