    memo = {}

    def count_ways(remaining, current_planet, visited_mask):
        """
        Count ways to complete path with 'remaining' steps needed
        from 'current_planet' given the visited 'mask' of previous planets.
        """
        if remaining == 1:
            # Count valid next planets
            count = 0
            for next_planet in range(1, min(n, current_planet + m) + 1):
                if not (visited_mask & (1 << (next_planet - 1))):
                    count += 1
            return count % MOD

        state = (remaining, current_planet, visited_mask)
        if state in memo:
            return memo[state]

        total = 0
        for next_planet in range(1, min(n, current_planet + m) + 1):
            if not (visited_mask & (1 << (next_planet - 1))):
                total = (total + count_ways(remaining - 1, next_planet, 
                                              visited_mask | (1 << (next_planet - 1)))) % MOD

        memo[state] = total
        return total

    # Sum over all possible starting planets
    result = 0
    for start_planet in range(1, n + 1):
        result = (result + count_ways(k, start_planet, 1 << (start_planet - 1))) % MOD

    return str(result)

