def solution(s):
    """
    Solves the concentration of circles problem.

    Given N circles centered at (x,0) with radii 1 to N,
    and M circles centered at (y,0) with radii 1 to M,
    count how many regions the plane is divided into.
    """
    N, x, M, y = map(int, s.strip().split())
    d = abs(x - y)

    # If same center, circles don't intersect, just count concentric regions
    if d == 0:
        return str(N + M + 1)

    # Count intersection points between circles from different sets
    intersections = 0

    for i in range(1, N + 1):
        for j in range(1, M + 1):
            r1, r2 = i, j

            # Check if circles intersect
            if d > r1 + r2:
                continue  # Circles too far apart
            if d < abs(r1 - r2):
                continue  # One circle inside another without touching

            # Check for tangency or intersection
            if d == r1 + r2 or d == abs(r1 - r2):
                intersections += 1  # Tangent at 1 point
            else:
                intersections += 2  # Intersect at 2 points

    # Calculate regions using Euler's formula
    # Each intersection point adds a region
    regions = N + M + intersections

    return str(regions)

