def solution(n_str):
    # Remove any whitespace and convert to integer
    n = int(n_str.strip())

    # Handle edge case
    if n == 0:
        return str(0)

    # BFS to find minimum number of operations
    from collections import deque

    # visited dictionary to store minimum steps to reach each number
    visited = {n: 0}
    queue = deque([n])

    while queue:
        current = queue.popleft()
        steps = visited[current]

        if current == 0:
            return str(steps)

        # Get all digits present in the current number
        digits = set()
        temp = current
        while temp > 0:
            digits.add(temp % 10)
            temp //= 10

        # Try subtracting each digit
        for d in digits:
            next_num = current - d
            if next_num not in visited:
                visited[next_num] = steps + 1
                queue.append(next_num)

    return str(visited[0])

