def solution(input_string):
    """
    Solution for counting Fibonacci number decompositions.
    Uses meet-in-the-middle approach for efficiency with large inputs.
    """
    def generate_fibs(limit):
        """Generate Fibonacci numbers: F1=1, F2=2, Fi=Fi-1+Fi-2"""
        fibs = []
        if limit >= 1:
            fibs.append(1)
        if limit >= 2:
            a, b = 1, 2
            fibs.append(2)
            while b + a <= limit:
                a, b = b, a + b
                fibs.append(b)
        return fibs

    def count_decompositions(n, fibs):
        """Count ways to decompose n into distinct Fibonacci numbers."""
        # Filter to relevant Fibonacci numbers
        relevant = [f for f in fibs if f <= n]
        m = len(relevant)
        mid = m // 2

        # Generate all subset sums for first half
        left_sums = {0: 1}
        for i in range(mid):
            f = relevant[i]
            new_entries = {}
            for s, cnt in left_sums.items():
                ns = s + f
                if ns <= n:
                    new_entries[ns] = new_entries.get(ns, 0) + cnt
            left_sums.update(new_entries)

        # Generate all subset sums for second half
        right_sums = {0: 1}
        for i in range(mid, m):
            f = relevant[i]
            new_entries = {}
            for s, cnt in right_sums.items():
                ns = s + f
                if ns <= n:
                    new_entries[ns] = new_entries.get(ns, 0) + cnt
            right_sums.update(new_entries)

        # Count pairs that sum to n
        ans = 0
        for s, cnt in left_sums.items():
            target = n - s
            if target in right_sums:
                ans += cnt * right_sums[target]

        return ans

    lines = input_string.strip().split('\n')
    t = int(lines[0])
